import styled from 'styled-components'
import { cores } from '../../styles'
import bgheader from '../../assets/images.nova/Vector.svg'

export const HeaderBar = styled.header`
  background-color: ${cores.cinza};
  padding: 40px;
  height: 385px;
  display: flex;
  text-align: center;
  background-image: url(${bgheader});
  flex-direction: column; // Para empilhar os elementos verticalmente

  img {
    width: 125px;
    margin: 0 auto; // Centraliza a imagem horizontalmente
  }

  div {
    display: block; // A div é um bloco, empilhando os filhos
    width: 100%;
    height: 300px;
    position: relative; // Necessário para o h1 ser posicionado em relação à div

    h1 {
      font-size: 36px;
      font-weight: 900;
      width: 539px;
      line-height: 42.2px;
      margin: 0 auto;
      position: absolute; // Posiciona o h1 de forma independente dentro da div
      bottom: -10px;
      left: 50%;
      transform: translateX(-50%);
    }
  }
`

export const Links = styled.ul`
  display: flex;
  margin-left: 40px;
`

export const LinkItem = styled.li`
  margin-right: 16px;
`

export const LinkCart = styled.a`
  display: flex;

  img {
    margin-left: 16px;
  }
`
